contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _seq, bytes32 _bh, uint256 _overhead, uint256 _scalar) public {
        bool ok = true;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _bh, _overhead, _scalar) {
            ok = true;
        } catch {
            ok = false;
        }
        assert(!(ok && c.number() == _number && c.basefee() == _basefee) || ok);
    }

    receive() external payable {}
    fallback() external payable {}
}
